import java.io.IOException;
import java.io.OutputStream;

/** Counts the bytes the user's code prints. Generated by the visualizer; never stepped through. */
final class __Out extends OutputStream {
    /** Read by the recorder at every step. */
    static long written;

    private final OutputStream sink;

    __Out(OutputStream sink) {
        this.sink = sink;
    }

    @Override
    public void write(int b) throws IOException {
        sink.write(b);
        written++;
    }

    @Override
    public void write(byte[] b, int off, int len) throws IOException {
        sink.write(b, off, len);
        written += len;
    }

    @Override
    public void flush() throws IOException {
        sink.flush();
    }
}
